package pt.studymatch.domain;

import java.math.BigDecimal;
import org.springframework.test.util.ReflectionTestUtils;
import pt.studymatch.enums.CourseUnitType;

/**
 * Small helpers to build domain objects in unit tests, without a database.
 * Ids are set by hand because they are normally generated by the database.
 */
final class DomainFixtures {

    private static long nextId = 1;

    private DomainFixtures() {
    }

    static StudyPlan studyPlan() {
        return withId(new StudyPlan("Engenharia Informática", 3, 180));
    }

    static KnowledgeArea area(String name) {
        return withId(new KnowledgeArea(name, ""));
    }

    static CourseUnit courseUnit(StudyPlan plan, String code, int ects, KnowledgeArea area) {
        CourseUnit courseUnit = withId(new CourseUnit(plan, code, "UC " + code, ects, 1, 1, CourseUnitType.MANDATORY));
        courseUnit.setKnowledgeArea(area);
        return courseUnit;
    }

    static Student student(Integer entryGrade) {
        return withId(new Student("20240001", "Joana Silva", "encoded-password", 2024, entryGrade));
    }

    static CourseUnitEnrolment result(CourseUnit unit, double grade) {
        CourseUnitEnrolment result = new CourseUnitEnrolment(student(null), unit, AcademicYear.startingIn(2024), java.time.LocalDate.of(2024, 9, 1));
        result.recordGrade(BigDecimal.valueOf(grade));
        return result;
    }

    private static <T> T withId(T entity) {
        ReflectionTestUtils.setField(entity, "id", nextId++);
        return entity;
    }
}
